"""Document and chunk data models plus corpus loading."""
from __future__ import annotations

import json
import os
from dataclasses import dataclass, field
from typing import Any, Dict, List, Optional


@dataclass
class Document:
    """A source document with rich metadata."""

    id: str
    title: str
    content: str
    metadata: Dict[str, Any] = field(default_factory=dict)

    def get(self, key: str, default: Any = None) -> Any:
        return self.metadata.get(key, default)


@dataclass
class Chunk:
    """A fragment of a document, carrying inherited metadata."""

    doc_id: str
    title: str
    text: str
    metadata: Dict[str, Any] = field(default_factory=dict)
    chunk_index: int = 0

    def get(self, key: str, default: Any = None) -> Any:
        return self.metadata.get(key, default)


def load_corpus(path: Optional[str] = None) -> List[Document]:
    """Load documents from a JSON file.

    Expected JSON shape: a list of objects with at least ``id``, ``title``,
    ``content`` and any number of extra metadata fields.
    """
    if path is None:
        here = os.path.dirname(os.path.abspath(__file__))
        path = os.path.join(here, "..", "data", "sample_corpus.json")

    with open(path, "r", encoding="utf-8") as fh:
        records = json.load(fh)

    docs: List[Document] = []
    for record in records:
        doc_id = record.get("id")
        title = record.get("title", "")
        content = record.get("content", "")
        metadata = {
            key: value
            for key, value in record.items()
            if key not in ("id", "title", "content")
        }
        docs.append(Document(id=doc_id, title=title, content=content, metadata=metadata))
    return docs

"""Tokenization and TF-IDF vectorization (pure Python, dependency-free)."""
from __future__ import annotations

import math
import re
from typing import Dict, Iterable, List

_TOKEN_RE = re.compile(r"[a-z0-9]+")


def tokenize(text: str) -> List[str]:
    """Lowercase alphanumeric tokenization."""
    return _TOKEN_RE.findall(text.lower())


class TfidfVectorizer:
    """Incremental-fit TF-IDF vectorizer with sublinear term frequency.

    If numpy is available it is used for fast arithmetic; otherwise pure
    Python lists are used.
    """

    def __init__(self) -> None:
        self._vocab: Dict[str, int] = {}
        self._idf: Dict[str, float] = {}
        self._n_docs: int = 0

    @property
    def dim(self) -> int:
        return len(self._vocab)

    def fit(self, texts: Iterable[str]) -> "TfidfVectorizer":
        """Compute IDF statistics over the corpus."""
        doc_freq: Dict[str, int] = {}
        n = 0
        for text in texts:
            unique = set(tokenize(text))
            for term in unique:
                doc_freq[term] = doc_freq.get(term, 0) + 1
            n += 1

        self._n_docs = n
        self._vocab = {term: i for i, term in enumerate(sorted(doc_freq))}
        # Smoothed IDF keeps rare-but-meaningful terms informative.
        self._idf = {
            term: math.log((1.0 + n) / (1.0 + freq)) + 1.0
            for term, freq in doc_freq.items()
        }
        return self

    def transform(self, text: str) -> List[float]:
        """Return the TF-IDF vector for *text*."""
        vec = [0.0] * self.dim
        tf: Dict[str, int] = {}
        for term in tokenize(text):
            tf[term] = tf.get(term, 0) + 1
        for term, count in tf.items():
            index = self._vocab.get(term)
            if index is not None:
                weight = (1.0 + math.log(count)) * self._idf[term]
                vec[index] = weight
        return vec


def cosine_similarity(a: List[float], b: List[float]) -> float:
    """Cosine similarity between two equal-length vectors."""
    if len(a) != len(b):
        raise ValueError("vectors must have the same length")
    dot = 0.0
    norm_a = 0.0
    norm_b = 0.0
    for x, y in zip(a, b):
        dot += x * y
        norm_a += x * x
        norm_b += y * y
    if norm_a == 0.0 or norm_b == 0.0:
        return 0.0
    return dot / (math.sqrt(norm_a) * math.sqrt(norm_b))

"""Metadata-aware in-memory vector store."""
from __future__ import annotations

from typing import Any, Dict, List, Optional, Sequence

from .document import Chunk
from .embeddings import Embedder
from .tokenizer import cosine_similarity


class VectorStore:
    """Base interface for a metadata-aware vector store."""

    def add(self, chunks: Sequence[Chunk]) -> None:  # pragma: no cover
        raise NotImplementedError

    def search(
        self,
        query_vector: List[float],
        k: int = 5,
        metadata_filter: Optional[Dict[str, Any]] = None,
    ) -> List[Chunk]:  # pragma: no cover
        raise NotImplementedError


class InMemoryVectorStore(VectorStore):
    """A simple, dependency-free vector store.

    Supports exact cosine similarity search plus optional metadata filtering
    applied *before* ranking (so filters act as hard constraints).
    """

    def __init__(self, embedder: Embedder) -> None:
        self._embedder = embedder
        self._chunks: List[Chunk] = []
        self._vectors: List[List[float]] = []

    def add(self, chunks: Sequence[Chunk]) -> None:
        texts = [chunk.text for chunk in chunks]
        vectors = self._embedder.embed(texts)
        self._chunks.extend(chunks)
        self._vectors.extend(vectors)

    @property
    def size(self) -> int:
        return len(self._chunks)

    def _passes_filter(self, chunk: Chunk, metadata_filter: Dict[str, Any]) -> bool:
        for key, expected in metadata_filter.items():
            actual = chunk.get(key)
            if isinstance(expected, (list, tuple, set)):
                if actual not in expected:
                    return False
            elif isinstance(expected, dict) and "min" in expected or isinstance(
                expected, dict
            ) and "max" in expected:
                # Range filter: {"min": x, "max": y}
                minimum = expected.get("min")
                maximum = expected.get("max")
                try:
                    value = float(actual)  # type: ignore[arg-type]
                except (TypeError, ValueError):
                    return False
                if minimum is not None and value < float(minimum):
                    return False
                if maximum is not None and value > float(maximum):
                    return False
            else:
                if actual != expected:
                    return False
        return True

    def search(
        self,
        query_vector: List[float],
        k: int = 5,
        metadata_filter: Optional[Dict[str, Any]] = None,
    ) -> List[Chunk]:
        """Return top-k chunks by cosine similarity.

        When ``metadata_filter`` is provided it is applied first (hard
        constraint): chunks that fail the filter never appear in the results.
        """
        metadata_filter = metadata_filter or {}

        scored: List[tuple[float, int]] = []
        for index, vector in enumerate(self._vectors):
            chunk = self._chunks[index]
            if not self._passes_filter(chunk, metadata_filter):
                continue
            score = cosine_similarity(query_vector, vector)
            scored.append((score, index))

        scored.sort(key=lambda item: item[0], reverse=True)
        return [self._chunks[index] for _, index in scored[:k]]

"""Metadata filtering and ranking.

Two complementary mechanisms are provided:

* :class:`MetadataFilter` — hard constraints (equality, membership, ranges,
  date windows). Documents that fail a filter are excluded.
* :class:`MetadataRanker` — soft boosts that re-rank the survivors based on
  metadata *relevance to the query* (recency, source credibility, category
  match, tag overlap, audience match).

Filters and boosts are fully configurable, so teams can encode their own
domain priorities (e.g. prefer regulatory docs, or newer security advisories)
without touching retrieval code.
"""
from __future__ import annotations

import re
from dataclasses import dataclass, field
from datetime import date, datetime
from typing import Any, Callable, Dict, List, Optional, Tuple

from .document import Chunk

# ---------------------------------------------------------------------------
# Query metadata parsing
# ---------------------------------------------------------------------------

_FIELD_TOKEN = re.compile(
    r"(?P<key>[a-z_][a-z0-9_]*)\s*:\s*(?P<value>[\w,\.\-\/]+)", re.IGNORECASE
)


def parse_query_metadata(query: str) -> Tuple[str, Dict[str, Any]]:
    """Extract ``key:value`` constraints from a query.

    Returns ``(clean_query, filters)`` where *filters* maps metadata field
    names to expected values. Comma-separated values become membership lists
    (e.g. ``tags:storage,backup``).

    Example::

        parse_query_metadata("category:security rotate api keys after:2024-01-01")
        # -> ("rotate api keys", {"category": "security", "date": "2024-01-01"})
    """
    filters: Dict[str, Any] = {}
    remaining: List[str] = []

    for token in query.split():
        match = _FIELD_TOKEN.fullmatch(token.strip())
        if match:
            key = match.group("key").lower()
            value = match.group("value")
            if "," in value:
                filters[key] = value.split(",")
            else:
                filters[key] = value
        else:
            remaining.append(token)

    return " ".join(remaining), filters


# ---------------------------------------------------------------------------
# Hard filtering
# ---------------------------------------------------------------------------

_DATE_KEYS = ("date", "published", "updated", "created")


@dataclass
class MetadataFilter:
    """Applies hard metadata constraints to a candidate chunk."""

    constraints: Dict[str, Any] = field(default_factory=dict)

    def matches(self, chunk: Chunk) -> bool:
        """True when the chunk satisfies every constraint."""
        for key, expected in self.constraints.items():
            actual = chunk.get(key)
            if not self._match_value(actual, expected):
                return False
        return True

    @staticmethod
    def _match_value(actual: Any, expected: Any) -> bool:
        if isinstance(expected, (list, tuple, set)):
            return actual in expected

        if isinstance(expected, dict):
            # Range / comparison constraints:
            #   {"min": ..., "max": ..., "gt": ..., "lt": ..., "gte": ..., "lte": ...}
            if actual is None:
                return False
            if key := expected.get("min") is not None:
                if not MetadataFilter._compare(actual, ">=", key):
                    return False
            if key := expected.get("max") is not None:
                if not MetadataFilter._compare(actual, "<=", key):
                    return False
            if key := expected.get("gt") is not None:
                if not MetadataFilter._compare(actual, ">", key):
                    return False
            if key := expected.get("lt") is not None:
                if not MetadataFilter._compare(actual, "<", key):
                    return False
            if key := expected.get("gte") is not None:
                if not MetadataFilter._compare(actual, ">=", key):
                    return False
            if key := expected.get("lte") is not None:
                if not MetadataFilter._compare(actual, "<=", key):
                    return False
            return True

        if isinstance(expected, str) and expected.startswith(">") or isinstance(
            expected, str
        ) and expected.startswith("<"):
            op = expected[0]
            target = expected[1:].strip()
            return MetadataFilter._compare(actual, op, target)

        return actual == expected

    @staticmethod
    def _compare(actual: Any, op: str, target: Any) -> bool:
        try:
            left = MetadataFilter._coerce(actual)
            right = MetadataFilter._coerce(target)
        except (TypeError, ValueError):
            return False
        if op == ">":
            return left > right
        if op == ">=":
            return left >= right
        if op == "<":
            return left < right
        if op == "<=":
            return left <= right
        return False

    @staticmethod
    def _coerce(value: Any) -> float:
        if isinstance(value, (int, float)):
            return float(value)
        if isinstance(value, (datetime, date)):
            return value.toordinal()
        text = str(value).strip()
        # Try date first so ISO dates compare correctly.
        try:
            return datetime.fromisoformat(text).date().toordinal()
        except ValueError:
            pass
        return float(text)

    def __bool__(self) -> bool:
        return bool(self.constraints)


# ---------------------------------------------------------------------------
# Soft ranking boosts
# ---------------------------------------------------------------------------


@dataclass
class BoostRule:
    """One configurable metadata boost.

    A boost multiplies the semantic score of matching chunks (boost >= 1.0).

    Modes:
      * ``match``: chunk value equals the rule value (case-insensitive).
      * ``contains``: chunk value contains the rule value as a substring.
      * ``tag_overlap``: intersection size between rule values (list) and the
        chunk's list value, scaled by ``per_overlap``.
      * ``recency``: newer chunks get more boost, with ``half_life_days``
        controlling how quickly old content is discounted.
      * ``rating``: scale by the chunk's numeric field (e.g. source_rating).
    """

    field: str
    boost: float = 1.0
    mode: str = "match"  # match | contains | tag_overlap | recency | rating
    value: Any = None
    half_life_days: float = 365.0
    per_overlap: float = 0.15

    def apply(self, chunk: Chunk) -> float:
        """Return the multiplier for *chunk* (1.0 when the rule does not fire)."""
        actual = chunk.get(self.field)
        mode = self.mode

        if mode == "recency":
            return self._recency_boost(actual)

        if mode == "rating":
            try:
                rating = float(actual)  # type: ignore[arg-type]
            except (TypeError, ValueError):
                return 1.0
            return 1.0 + (self.boost - 1.0) * max(0.0, min(1.0, rating))

        if actual is None:
            return 1.0

        if mode == "match":
            if str(actual).lower() == str(self.value).lower():
                return self.boost
            return 1.0

        if mode == "contains":
            if str(self.value).lower() in str(actual).lower():
                return self.boost
            return 1.0

        if mode == "tag_overlap":
            rule_values = set(str(t).lower() for t in (self.value or []))
            chunk_values = set(str(t).lower() for t in actual)
            overlap = len(rule_values & chunk_values)
            return 1.0 + overlap * self.per_overlap * (self.boost - 1.0)

        return 1.0

    def _recency_boost(self, value: Any) -> float:
        try:
            parsed = datetime.fromisoformat(str(value)).date()
        except (TypeError, ValueError):
            return 1.0
        age_days = (date.today() - parsed).days
        if age_days < 0:
            age_days = 0.0
        # Exponential decay: boost halves every half_life_days.
        factor = 0.5 ** (age_days / self.half_life_days)
        return 1.0 + (self.boost - 1.0) * factor


@dataclass
class MetadataRanker:
    """Combines semantic similarity with metadata boosts.

    final_score = semantic_score * boost_multiplier

    where ``boost_multiplier`` is the product of every matching :class:`BoostRule`.
    """

    rules: List[BoostRule] = field(default_factory=list)

    def add_rule(self, rule: BoostRule) -> "MetadataRanker":
        self.rules.append(rule)
        return self

    def boost_for(self, chunk: Chunk, query_terms: List[str]) -> float:
        """Compute the combined boost multiplier for a chunk.

        ``query_terms`` is used for automatic term-overlap boosts (title and
        tags matching query vocabulary).
        """
        multiplier = 1.0
        for rule in self.rules:
            multiplier *= rule.apply(chunk)

        # Automatic soft boost when query terms appear in the title or tags.
        title = (chunk.title or "").lower()
        tags = [str(t).lower() for t in chunk.get("tags", [])]
        for term in query_terms:
            if term in title:
                multiplier *= 1.05
            if any(term in tag for tag in tags):
                multiplier *= 1.03

        return multiplier

    def rank(self, chunk: Chunk, semantic_score: float, query_terms: List[str]) -> float:
        return semantic_score * self.boost_for(chunk, query_terms)


# ---------------------------------------------------------------------------
# Default policies
# ---------------------------------------------------------------------------


def default_boost_rules() -> List[BoostRule]:
    """A sensible default policy.

    Teams should customize these to encode their domain priorities. This is a
    generic, transparent example — not domain-specific keyword hacking.
    """
    return [
        BoostRule(field="source_rating", boost=1.15, mode="rating"),
        BoostRule(field="date", boost=1.10, mode="recency", half_life_days=365.0),
        BoostRule(field="category", boost=1.10, mode="tag_overlap", per_overlap=0.10),
    ]


def build_ranked_scores(
    chunks: List[Chunk],
    semantic_scores: List[float],
    query_terms: List[str],
    ranker: MetadataRanker,
) -> List[Tuple[Chunk, float, float]]:
    """Return ``(chunk, semantic_score, final_score)`` sorted by final score."""
    scored = [
        (chunk, sem, ranker.rank(chunk, sem, query_terms))
        for chunk, sem in zip(chunks, semantic_scores)
    ]
    scored.sort(key=lambda item: item[2], reverse=True)
    return scored

"""Metadata filtering and ranking.

Two complementary mechanisms are provided:

* :class:`MetadataFilter` — hard constraints (equality, membership, ranges,
  date windows). Documents that fail a filter are excluded.
* :class:`MetadataRanker` — soft boosts that re-rank the survivors based on
  metadata *relevance to the query* (recency, source credibility, tag overlap).
  Boosts are configurable, so teams can encode their own domain priorities
  without touching retrieval code.
"""
from __future__ import annotations

import re
from dataclasses import dataclass, field
from datetime import date, datetime
from typing import Any, Dict, List, Optional, Tuple

from .document import Chunk

# ---------------------------------------------------------------------------
# Query metadata parsing
# ---------------------------------------------------------------------------

_FIELD_TOKEN = re.compile(
    r"(?P<key>[a-z_][a-z0-9_]*)\s*:\s*(?P<value>[\w,\.\-\/]+)", re.IGNORECASE
)

# Alias translation for intuitive query syntax.
_ALIASES = {
    "after": ("date", "min"),
    "since": ("date", "min"),
    "before": ("date", "max"),
    "until": ("date", "max"),
    "cat": ("category", None),
}


def parse_query_metadata(query: str) -> Tuple[str, Dict[str, Any]]:
    """Extract ``key:value`` constraints from a query.

    Returns ``(clean_query, filters)`` where *filters* maps metadata field
    names to expected values. Comma-separated values become membership lists
    (e.g. ``tags:storage,backup``). Date aliases ``after``/``before`` become
    range constraints on the ``date`` field.

    Example::

        parse_query_metadata("category:security rotate api keys after:2024-01-01")
        # -> ("rotate api keys", {"category": "security", "date": {"min": "2024-01-01"}})
    """
    filters: Dict[str, Any] = {}
    remaining: List[str] = []

    for token in query.split():
        match = _FIELD_TOKEN.fullmatch(token.strip())
        if match:
            key = match.group("key").lower()
            value = match.group("value")
            field_name, range_key = _ALIASES.get(key, (key, None))
            if "," in value and field_name in ("tags", "category", "author"):
                value = value.split(",")
            if range_key is not None:
                # Merge with any existing range constraint on the same field.
                existing = filters.get(field_name)
                if isinstance(existing, dict):
                    existing[range_key] = value
                else:
                    filters[field_name] = {range_key: value}
            else:
                filters[field_name] = value
        else:
            remaining.append(token)

    return " ".join(remaining), filters


