# Default policy + scoring helper
# ---------------------------------------------------------------------------


def default_boost_rules() -> List[BoostRule]:
    """A sensible, generic default policy.

    Customize these to encode domain priorities (e.g. prefer regulatory
    documents, or newer security advisories). The policy below prefers
    credible sources and recent content, and rewards tag overlap.
    """
    return [
        BoostRule(field="source_rating", boost=1.15, mode="rating"),
        BoostRule(field="date", boost=1.10, mode="recency", half_life_days=365.0),
        BoostRule(
            field="tags",
            boost=1.10,
            mode="tag_overlap",
            per_overlap=0.10,
        ),
    ]


def build_ranked_scores(
    chunks: List[Chunk],
    semantic_scores: List[float],
    query_terms: List[str],
    ranker: MetadataRanker,
) -> List[Tuple[Chunk, float, float]]:
    """Return ``(chunk, semantic_score, final_score)`` sorted by final score."""
    scored = [
        (chunk, semantic, ranker.rank(chunk, semantic, query_terms))
        for chunk, semantic in zip(chunks, semantic_scores)
    ]
    scored.sort(key=lambda item: item[2], reverse=True)
    return scored

"""Metadata filtering and ranking.

Two complementary mechanisms are provided:

* :class:`MetadataFilter` — hard constraints (equality, membership, ranges,
  date windows). Documents that fail a filter are excluded.
* :class:`MetadataRanker` — soft boosts that re-rank the survivors based on
  metadata *relevance to the query* (recency, source credibility, tag overlap).
  Boosts are configurable, so teams can encode their own domain priorities
  without touching retrieval code.
"""
from __future__ import annotations

import re
from dataclasses import dataclass, field
from datetime import date, datetime
from typing import Any, Dict, List, Optional, Tuple

from .document import Chunk

# ---------------------------------------------------------------------------
# Query metadata parsing
# ---------------------------------------------------------------------------

_FIELD_TOKEN = re.compile(
    r"(?P<key>[a-z_][a-z0-9_]*)\s*:\s*(?P<value>[\w,\.\-\/]+)", re.IGNORECASE
)

# Alias translation for intuitive query syntax.
_ALIASES = {
    "after": ("date", "min"),
    "since": ("date", "min"),
    "before": ("date", "max"),
    "until": ("date", "max"),
    "cat": ("category", None),
}


def parse_query_metadata(query: str) -> Tuple[str, Dict[str, Any]]:
    """Extract ``key:value`` constraints from a query.

    Returns ``(clean_query, filters)`` where *filters* maps metadata field
    names to expected values. Comma-separated values become membership lists
    (e.g. ``tags:storage,backup``). Date aliases ``after``/``before`` become
    range constraints on the ``date`` field.

    Example::

        parse_query_metadata("category:security rotate api keys after:2024-01-01")
        # -> ("rotate api keys", {"category": "security", "date": {"min": "2024-01-01"}})
    """
    filters: Dict[str, Any] = {}
    remaining: List[str] = []

    for token in query.split():
        match = _FIELD_TOKEN.fullmatch(token.strip())
        if match:
            key = match.group("key").lower()
            value = match.group("value")
            field_name, range_key = _ALIASES.get(key, (key, None))
            if "," in value and field_name in ("tags", "category", "author"):
                value = value.split(",")
            if range_key is not None:
                # Merge with any existing range constraint on the same field.
                existing = filters.get(field_name)
                if isinstance(existing, dict):
                    existing[range_key] = value
                else:
                    filters[field_name] = {range_key: value}
            else:
                filters[field_name] = value
        else:
            remaining.append(token)

    return " ".join(remaining), filters


# ---------------------------------------------------------------------------
# Hard filtering
# ---------------------------------------------------------------------------


@dataclass
class MetadataFilter:
    """Applies hard metadata constraints to a candidate chunk."""

    constraints: Dict[str, Any] = field(default_factory=dict)

    def matches(self, chunk: Chunk) -> bool:
        """True when the chunk satisfies every constraint."""
        for key, expected in self.constraints.items():
            actual = chunk.get(key)
            if not self._match_value(actual, expected):
                return False
        return True

    @staticmethod
    def _match_value(actual: Any, expected: Any) -> bool:
        if isinstance(expected, (list, tuple, set)):
            return actual in expected

        if isinstance(expected, dict):
            # Range / comparison constraints:
            #   {"min": ..., "max": ..., "gt": ..., "lt": ...}
            if actual is None:
                return False
            minimum = expected.get("min")
            if minimum is not None and not MetadataFilter._compare(actual, ">=", minimum):
                return False
            maximum = expected.get("max")
            if maximum is not None and not MetadataFilter._compare(actual, "<=", maximum):
                return False
            gt = expected.get("gt")
            if gt is not None and not MetadataFilter._compare(actual, ">", gt):
                return False
            lt = expected.get("lt")
            if lt is not None and not MetadataFilter._compare(actual, "<", lt):
                return False
            return True

        if isinstance(expected, str) and (
            expected.startswith(">") or expected.startswith("<")
        ):
            op = expected[0]
            target = expected[1:].strip()
            return MetadataFilter._compare(actual, op, target)

        return actual == expected

    @staticmethod
    def _compare(actual: Any, op: str, target: Any) -> bool:
        try:
            left = MetadataFilter._coerce(actual)
            right = MetadataFilter._coerce(target)
        except (TypeError, ValueError):
            return False
        if op == ">":
            return left > right
        if op == ">=":
            return left >= right
        if op == "<":
            return left < right
        if op == "<=":
            return left <= right
        return False

    @staticmethod
    def _coerce(value: Any) -> float:
        if isinstance(value, (int, float)):
            return float(value)
        if isinstance(value, (datetime, date)):
            return float(value.toordinal())
        text = str(value).strip()
        # Try dates first so ISO dates compare correctly.
        try:
            return float(datetime.fromisoformat(text).date().toordinal())
        except ValueError:
            pass
        return float(text)

    def __bool__(self) -> bool:
        return bool(self.constraints)


# ---------------------------------------------------------------------------
# Soft ranking boosts
# ---------------------------------------------------------------------------


@dataclass
class BoostRule:
    """One configurable metadata boost.

    A boost multiplies the semantic score of matching chunks (boost >= 1.0).

    Modes:
      * ``match``: chunk value equals the rule value (case-insensitive).
      * ``contains``: chunk value contains the rule value as a substring.
      * ``tag_overlap``: fraction of the chunk's tag list that overlaps the
        rule's ``value`` list; each overlapping tag adds ``per_overlap``.
      * ``recency``: newer chunks get more boost, with ``half_life_days``
        controlling how quickly old content is discounted.
      * ``rating``: scale by the chunk's numeric field (e.g. ``source_rating``)
        mapped through the rule's boost range.
    """

    field: str
    boost: float = 1.0
    mode: str = "match"  # match | contains | tag_overlap | recency | rating
    value: Any = None
    half_life_days: float = 365.0
    per_overlap: float = 0.15

    def apply(self, chunk: Chunk) -> float:
        """Return the multiplier for *chunk* (1.0 when the rule does not fire)."""
        actual = chunk.get(self.field)
        mode = self.mode

        if mode == "recency":
            return self._recency_boost(actual)

        if mode == "rating":
            try:
                rating = float(actual)  # type: ignore[arg-type]
            except (TypeError, ValueError):
                return 1.0
            return 1.0 + (self.boost - 1.0) * max(0.0, min(1.0, rating))

        if actual is None:
            return 1.0

        if mode == "match":
            if str(actual).lower() == str(self.value).lower():
                return self.boost
            return 1.0

        if mode == "contains":
            if str(self.value).lower() in str(actual).lower():
                return self.boost
            return 1.0

        if mode == "tag_overlap":
            rule_values = set(str(t).lower() for t in (self.value or []))
            chunk_values = set(str(t).lower() for t in actual)
            if not chunk_values:
                return 1.0
            overlap = len(rule_values & chunk_values)
            return 1.0 + overlap * self.per_overlap * (self.boost - 1.0)

        return 1.0

    def _recency_boost(self, value: Any) -> float:
        try:
            parsed = datetime.fromisoformat(str(value)).date()
        except (TypeError, ValueError):
            return 1.0
        age_days = (date.today() - parsed).days
        if age_days < 0:
            age_days = 0.0
        # Exponential decay: the boost halves every half_life_days.
        factor = 0.5 ** (age_days / self.half_life_days)
        return 1.0 + (self.boost - 1.0) * factor


@dataclass
class MetadataRanker:
    """Combines semantic similarity with metadata boosts.

    final_score = semantic_score * boost_multiplier

    where ``boost_multiplier`` is the product of every matching
    :class:`BoostRule` and an automatic term-overlap boost for query terms
    found in the chunk's title or tags.
    """

    rules: List[BoostRule] = field(default_factory=list)

    def add_rule(self, rule: BoostRule) -> "MetadataRanker":
        self.rules.append(rule)
        return self

    def boost_for(self, chunk: Chunk, query_terms: List[str]) -> float:
        """Compute the combined boost multiplier for a chunk."""
        multiplier = 1.0
        for rule in self.rules:
            multiplier *= rule.apply(chunk)

        title = (chunk.title or "").lower()
        tags = [str(t).lower() for t in chunk.get("tags", [])]
        for term in query_terms:
            if len(term) < 3:
                continue
            if term in title:
                multiplier *= 1.05
            if any(term in tag for tag in tags):
                multiplier *= 1.03

        return multiplier

    def rank(self, chunk: Chunk, semantic_score: float, query_terms: List[str]) -> float:
        return semantic_score * self.boost_for(chunk, query_terms)


# ---------------------------------------------------------------------------
# Default policy + scoring helper
# ---------------------------------------------------------------------------


def default_boost_rules() -> List[BoostRule]:
    """A sensible, generic default policy.

    Customize these to encode domain priorities (e.g. prefer regulatory
    documents, or newer security advisories). The policy below prefers
    credible sources and recent content. Query-driven tag/title overlap is
    applied automatically by :meth:`MetadataRanker.boost_for`.
    """
    return [
        BoostRule(field="source_rating", boost=1.15, mode="rating"),
        BoostRule(field="date", boost=1.10, mode="recency", half_life_days=365.0),
    ]


def build_ranked_scores(
    chunks: List[Chunk],
    semantic_scores: List[float],
    query_terms: List[str],
    ranker: MetadataRanker,
) -> List[Tuple[Chunk, float, float]]:
    """Return ``(chunk, semantic_score, final_score)`` sorted by final score."""
    scored = [
        (chunk, semantic, ranker.rank(chunk, semantic, query_terms))
        for chunk, semantic in zip(chunks, semantic_scores)
    ]
    scored.sort(key=lambda item: item[2], reverse=True)
    return scored
